#include "RecentProtocol.h"
#include <sodium.h>
#include <algorithm>
#include <limits>
#include <set>
namespace private_input::activity {namespace {
template<size_t N>Data raw(const std::array<unsigned char,N>&v){return {v.begin(),v.end()};}
template<size_t N>Data label(const char(&s)[N]){return bytes(std::string_view(s,N));}
Key derive(const Json&j,const Key&master,const Key&signer){Data salt=raw(parseId(j.at("group").str()));be64(salt,j.at("epoch").num());auto info=label("PrivateInput/recent-learning-key/v1");append(info,raw(parseId(j.at("sender").str())));append(info,raw(signer));Key prk{},key{};require(crypto_kdf_hkdf_sha256_extract(prk.data(),salt.data(),salt.size(),master.data(),32)==0,"recent HKDF extract");int rc=crypto_kdf_hkdf_sha256_expand(key.data(),32,reinterpret_cast<const char*>(info.data()),info.size(),prk.data());sodium_memzero(prk.data(),32);require(rc==0,"recent HKDF expand");return key;}
}
Data recentRequestCanonical(const Json&j){require(j.kind==Json::Kind::object&&j.fields.size()==8&&j.at("version").num()==1&&j.at("operation").num()>=1&&j.at("operation").num()<=3,"recent request shape");auto payload=unbase64(j.at("body").str());require(payload.size()<=3145728,"recent request body");auto canonical=label("PrivateInput/recency-request/v1");canonical.push_back(1);append(canonical,raw(parseId(j.at("group").str())));append(canonical,raw(parseId(j.at("sender").str())));append(canonical,raw(parseId(j.at("nonce").str())));be64(canonical,j.at("issuedAt").num());canonical.push_back(uint8_t(j.at("operation").num()));append(canonical,raw(sha256(payload)));return canonical;}
Json recentRequest(const Id&group,const GroupIdentity&i,uint8_t operation,const Json&body,uint64_t now){auto payload=body.dump();require(operation>=1&&operation<=3&&payload.size()<=3145728,"recent request bounds");auto j=Json::object({{"version",1},{"group",uuidText(group)},{"sender",uuidText(i.device)},{"nonce",uuidText(newId())},{"issuedAt",now},{"operation",int(operation)},{"body",base64(bytes(payload))},{"signature",""}});j["signature"]=base64(sign(recentRequestCanonical(j),i.signingSeed));return j;}
Data recentHeader(const Json&j){require(j.kind==Json::Kind::object&&j.fields.size()==9&&j.at("version").num()==1&&j.at("epoch").num()>0&&j.at("expiresAt").num()>j.at("issuedAt").num()&&j.at("expiresAt").num()-j.at("issuedAt").num()<=604800,"recent envelope metadata");require(unbase64(j.at("sealed").str()).size()<=2097180,"recent sealed bound");auto h=label("PrivateInput/recent-learning-envelope/v1");h.push_back(1);append(h,raw(parseId(j.at("group").str())));append(h,raw(parseId(j.at("sender").str())));append(h,raw(parseId(j.at("event").str())));be64(h,j.at("epoch").num());be64(h,j.at("issuedAt").num());be64(h,j.at("expiresAt").num());return h;}
Json sealRecent(const Json&payload,const protocol::VerifiedMembership&m,const GroupIdentity&i,const Key&master,uint64_t now){validateRecent(payload);require(now<=std::numeric_limits<uint64_t>::max()-604800,"recent expiry overflow");auto trust=m.trust(protocol::MembershipDomain::learning);require(trust.members.count(i.device)&&trust.members.at(i.device)==publicKey(i.signingSeed),"recent sender trust");auto j=Json::object({{"version",1},{"group",uuidText(m.anchor().group)},{"sender",uuidText(i.device)},{"event",uuidText(newId())},{"epoch",m.statement().epoch},{"issuedAt",now},{"expiresAt",now+604800},{"sealed",""},{"signature",""}});auto h=recentHeader(j),plain=bytes(payload.dump());auto key=derive(j,master,publicKey(i.signingSeed));Data box(plain.size()+28);randombytes_buf(box.data(),12);unsigned long long n=0;int rc=crypto_aead_chacha20poly1305_ietf_encrypt(box.data()+12,&n,plain.data(),plain.size(),h.data(),h.size(),nullptr,box.data(),key.data());sodium_memzero(key.data(),32);require(rc==0&&n==plain.size()+16,"recent seal");j["sealed"]=base64(box);append(h,box);j["signature"]=base64(sign(h,i.signingSeed));return j;}
Json openRecent(const Json&j,const protocol::VerifiedMembership&m,const Key&master,uint64_t now){auto header=recentHeader(j);require(parseId(j.at("group").str())==m.anchor().group&&j.at("epoch").num()==m.statement().epoch&&j.at("expiresAt").num()>now&&(j.at("issuedAt").num()<=now||j.at("issuedAt").num()-now<=300),"recent context/time");auto trust=m.trust(protocol::MembershipDomain::learning);auto sender=parseId(j.at("sender").str());require(trust.members.count(sender),"recent unknown sender");auto box=unbase64(j.at("sealed").str()),signature=unbase64(j.at("signature").str(),64);require(box.size()>=28,"recent truncated box");auto authenticated=header;append(authenticated,box);require(crypto_sign_verify_detached(signature.data(),authenticated.data(),authenticated.size(),trust.members.at(sender).data())==0,"recent signature");auto key=derive(j,master,trust.members.at(sender));Data plain(box.size()-28);unsigned long long n=0;int rc=crypto_aead_chacha20poly1305_ietf_decrypt(plain.data(),&n,nullptr,box.data()+12,box.size()-12,header.data(),header.size(),box.data(),key.data());sodium_memzero(key.data(),32);require(rc==0&&n==plain.size(),"recent AEAD");return validateRecent(Json::parse(std::string(plain.begin(),plain.end()),2097152,32,262144));}
void validateRecentStatus(const Json&s,const Json&request,const protocol::VerifiedMembership&m,uint64_t begin,uint64_t end){require(end>=begin&&end-begin<=10000,"recent RTT");require(s.at("version").num()==1&&parseId(s.at("group").str())==parseId(request.at("group").str())&&parseId(s.at("sender").str())==parseId(request.at("sender").str())&&parseId(s.at("nonce").str())==parseId(request.at("nonce").str())&&parseId(s.at("group").str())==m.anchor().group&&s.at("epoch").num()==m.statement().epoch&&s.at("membershipRevision").num()==m.statement().revision,"recent response binding");auto missing=s.at("missing");require(missing.kind==Json::Kind::array&&missing.items.size()<=64,"recent missing bounds");std::set<Id>seen;auto trust=m.trust(protocol::MembershipDomain::learning);for(const auto&id:missing.items){auto parsed=parseId(id.str());require(trust.members.count(parsed)&&seen.insert(parsed).second,"recent missing identity");}require(s.at("ready").boolean()==seen.empty(),"recent readiness");auto time=s.at("serverTime").num(),issued=request.at("issuedAt").num(),day=s.at("referenceDay").num();require(day>=90&&day<=3000000&&day==time/86400&&(time>=issued?time-issued:issued-time)<300,"recent server time");if(s.has("publishedEvent")&&!s.at("publishedEvent").str().empty())(void)parseId(s.at("publishedEvent").str());auto op=request.at("operation").num();if(op==2){require(s.at("accepted").boolean(),"recent rejected publication");(void)parseId(s.at("event").str());}if(op==3){auto next=s.at("next").str();bool none=!s.has("envelope")||s.at("envelope").kind==Json::Kind::null;require(none==next.empty(),"recent cursor pair");if(!next.empty())require(uuidText(parseId(next))==uuidText(parseId(s.at("envelope").at("sender").str()))&&parseId(next)!=parseId(request.at("sender").str()),"recent cursor sender");}}
}
